from pathlib import Path

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse

app = FastAPI()

REPORT_PATH = Path(__file__).resolve().parent.parent / "reports" / "build_report.txt"


def send_welcome(email: str):
    print('sending to', email)


@app.post('/signup')
def signup(email: str):
    send_welcome(email)
    return {'ok': True}


@app.get('/reports/build_report.txt')
def download_build_report():
    """Serve the latest build report as a downloadable file."""
    if not REPORT_PATH.is_file():
        raise HTTPException(status_code=404, detail='build report not published')
    return FileResponse(
        REPORT_PATH,
        media_type='text/plain',
        filename='build_report.txt',
    )
